Aqui está a solução completa para o problema **Trem da mina**, estruturada segundo o Método de Pólya.

---

### 1. COMPREENSÃO DO PROBLEMA
- **Objetivo**: Determinar o menor percurso para que um trem de comprimento $T$, entrando pela estação $X$, consiga percorrer a mina e sair pela mesma estação $X$ sem dar marcha-a-ré e sem colidir consigo mesmo.
- **Estrutura da Rede**: O grafo é não direcionado e cada estação pertence a no máximo um ciclo simples (grafo do tipo cacto com ciclos disjuntos em vértices).
- **Condição de Movimento do Trem**: Para que o trem possa retornar à estação de entrada sem marcha-a-ré e sem colidir consigo mesmo, ele deve entrar na mina, atingir um ciclo cujo comprimento total seja maior ou igual ao comprimento do trem ($L_{\text{ciclo}} \ge T$), dar a volta completa no ciclo, e retornar pelo mesmo caminho. O percurso total será $2 \times \text{dist}(X, \text{ciclo}) + L_{\text{ciclo}}$.
- **Limites e Entradas**:
  - $E \le 10^4$ estações, $R \le 2 \times 10^4$ ramos de trilho.
  - Comprimento das arestas $C \le 100$.
  - Consultas $K \le 100$. Comprimento do trem $T \le 10^5$.
  - Percurso total pode ultrapassar limites de inteiros de 32 bits? A distância máxima é da ordem de $10^4 \times 100 \times 2 + 10^4 \times 100 \approx 3 \times 10^6$, cabendo em um inteiro comum de 32 bits, mas usaremos `long long` por segurança contra overflow.

---

### 2. PLANEJAMENTO E DESIGN ALGORÍTMICO
1. **Identificação dos Ciclos**:
   - Como cada vértice pertence a no máximo um ciclo simples, podemos usar uma busca em profundidade (DFS) na floresta geradora para identificar todas as arestas de retorno (*back-edges*).
   - Ao encontrar uma aresta de retorno de $u$ para $v$ (onde $v$ é ancestral de $u$ na árvore DFS), reconstruímos o caminho de $u$ até $v$, obtendo todos os vértices que formam o ciclo e a soma das suas arestas ($L_{\text{ciclo}}$).
   - Atribuímos um identificador único para cada ciclo e associamos cada vértice pertencente a esse ciclo.
2. **Processamento das Consultas**:
   - Como $K \le 100$ e $E \le 10^4$, para cada consulta $(X, T)$ podemos rodar o algoritmo de **Dijkstra** a partir de $X$ para encontrar a menor distância de $X$ a todos os outros vértices.
   - Encontramos a distância mínima de $X$ a cada ciclo: $\text{dist}(X, \text{ciclo}_c) = \min_{v \in \text{ciclo}_c} d[v]$.
   - Dentre todos os ciclos que satisfazem $L_c \ge T$ e são alcançáveis a partir de $X$, encontramos o valor mínimo de $2 \times \text{dist}(X, \text{ciclo}_c) + L_c$.
   - Se nenhum ciclo for válido, a resposta é `-1`.
3. **Complexidade**:
   - Identificação dos ciclos via DFS: $O(E + R)$.
   - Cada consulta: Dijkstra em $O((E + R) \log E)$. Com $K \le 100$, o tempo total fica em torno de $100 \times 2 \cdot 10^4 \log_2(10^4) \approx 2.6 \times 10^7$ operações, executando em menos de 0.05 segundos.
   - Espaço: $O(E + R)$, consumindo menos de 5 MB de memória.

---

### 3. CODIFICAÇÃO EM C

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INF 0x3f3f3f3f3f3f3f3fLL

typedef struct {
    int to;
    int weight;
    int next;
} Edge;

typedef struct {
    int v;
    long long dist;
} HeapNode;

// Grafo usando lista de adjacência estática
int head[10005], edge_cnt;
Edge edges[40005];

void add_edge(int u, int v, int w) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].weight = w;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

// Estruturas para ciclos
int cycle_id[10005];
long long cycle_len[10005];
int num_cycles = 0;

// DFS para detecção de ciclos
int visited[10005];
int parent_node[10005];
int parent_edge_weight[10005];
int depth[10005];

void dfs_find_cycles(int u, int p, int d) {
    visited[u] = 1;
    depth[u] = d;
    for (int e = head[u]; e != -1; e = edges[e].next) {
        int v = edges[e].to;
        int w = edges[e].weight;
        if (v == p) continue;

        if (visited[v] == 1) { // Aresta de retorno (back-edge)
            if (depth[v] < depth[u]) {
                num_cycles++;
                long long length = w;
                int curr = u;
                while (curr != v) {
                    cycle_id[curr] = num_cycles;
                    length += parent_edge_weight[curr];
                    curr = parent_node[curr];
                }
                cycle_id[v] = num_cycles;
                cycle_len[num_cycles] = length;
            }
        } else if (visited[v] == 0) {
            parent_node[v] = u;
            parent_edge_weight[v] = w;
            dfs_find_cycles(v, u, d + 1);
        }
    }
    visited[u] = 2;
}

// Min-Heap para Dijkstra
HeapNode heap[40005];
int heap_size = 0;

void heap_push(int v, long long dist) {
    int i = heap_size++;
    heap[i].v = v;
    heap[i].dist = dist;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (heap[p].dist <= heap[i].dist) break;
        HeapNode tmp = heap[p];
        heap[p] = heap[i];
        heap[i] = tmp;
        i = p;
    }
}

HeapNode heap_pop(void) {
    HeapNode ret = heap[0];
    heap_size--;
    if (heap_size > 0) {
        heap[0] = heap[heap_size];
        int i = 0;
        while (2 * i + 1 < heap_size) {
            int left = 2 * i + 1;
            int right = 2 * i + 2;
            int best = left;
            if (right < heap_size && heap[right].dist < heap[left].dist) {
                best = right;
            }
            if (heap[i].dist <= heap[best].dist) break;
            HeapNode tmp = heap[i];
            heap[i] = heap[best];
            heap[best] = tmp;
            i = best;
        }
    }
    return ret;
}

long long dist[10005];
long long min_cycle_dist[10005];

int main(void) {
    int E, R;
    if (scanf("%d %d", &E, &R) != 2) return 0;

    memset(head, -1, sizeof(head));
    edge_cnt = 0;

    for (int i = 0; i < R; i++) {
        int u, v, w;
        scanf("%d %d %d", &u, &v, &w);
        add_edge(u, v, w);
        add_edge(v, u, w);
    }

    // Identificar ciclos
    for (int i = 1; i <= E; i++) {
        if (!visited[i]) {
            dfs_find_cycles(i, 0, 1);
        }
    }

    int K;
    if (scanf("%d", &K) != 1) return 0;

    while (K--) {
        int X;
        long long T;
        scanf("%d %lld", &X, &T);

        // Dijkstra a partir de X
        for (int i = 1; i <= E; i++) dist[i] = INF;
        for (int i = 1; i <= num_cycles; i++) min_cycle_dist[i] = INF;

        dist[X] = 0;
        heap_size = 0;
        heap_push(X, 0);

        while (heap_size > 0) {
            HeapNode top = heap_pop();
            int u = top.v;
            long long d = top.dist;

            if (d > dist[u]) continue;

            for (int e = head[u]; e != -1; e = edges[e].next) {
                int v = edges[e].to;
                long long w = edges[e].weight;
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    heap_push(v, dist[v]);
                }
            }
        }

        // Calcula a menor distância de X até cada ciclo
        for (int i = 1; i <= E; i++) {
            if (cycle_id[i] > 0 && dist[i] < INF) {
                int cid = cycle_id[i];
                if (dist[i] < min_cycle_dist[cid]) {
                    min_cycle_dist[cid] = dist[i];
                }
            }
        }

        // Encontra o ciclo com menor custo total
        long long best_ans = INF;
        for (int cid = 1; cid <= num_cycles; cid++) {
            if (cycle_len[cid] >= T && min_cycle_dist[cid] < INF) {
                long long cost = 2 * min_cycle_dist[cid] + cycle_len[cid];
                if (cost < best_ans) {
                    best_ans = cost;
                }
            }
        }

        if (best_ans == INF) {
            printf("-1\n");
        } else {
            printf("%lld\n", best_ans);
        }
    }

    return 0;
}
```

